# D16 · Part 0~7 · 오늘의 흐름 전체: 글자 → 정규화 → 발음 → 길이 → mel → 소리 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d16_flow.py   (인터넷 · GPU · 마이크 불필요)
#   정규화 · G2P · 자모 · duration · Length Regulator · 업샘플까지 한 줄로 이어 확인 (신경망 대신 규칙 · 사인파)
import re
import numpy as np

def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")

DIGITS = "영일이삼사오육칠팔구"
ONES = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉"]
TENS = ["", "열", "스물", "서른", "마흔", "쉰", "예순", "일흔", "여든", "아흔"]
NATIVE_COUNTERS = ["시간", "개", "명", "살", "마리", "권", "잔", "병", "장", "달", "시"]   # '시간'을 '시'보다 먼저


def sino(n: int) -> str:
    """한자어 수: 12500 -> 만이천오백"""
    if n == 0:
        return "영"
    out = ""
    for big in ["", "만", "억", "조"]:                  # 네 자리씩 끊어 읽기
        chunk, n = n % 10000, n // 10000
        s = ""
        for i, unit in enumerate(["", "십", "백", "천"]):
            d, chunk = chunk % 10, chunk // 10
            if d:
                s = ("" if d == 1 and i > 0 else DIGITS[d]) + unit + s
        if s:
            out = ("" if s == "일" and big == "만" else s) + big + out
        if n == 0:
            break
    return out


def native(n: int) -> str:
    """고유어 수: 3 -> 세, 20 -> 스무, 21 -> 스물한"""
    if not 0 < n < 100:
        return sino(n)
    return "스무" if n == 20 else TENS[n // 10] + ONES[n % 10]


def read_count(n: int, unit: str) -> str:
    return (native(n) if unit in NATIVE_COUNTERS else sino(n)) + " " + unit


def read_number(s: str) -> str:
    s = s.replace(",", "")
    if "." in s:
        a, b = s.split(".", 1)
        return sino(int(a)) + "점" + "".join(DIGITS[int(c)] for c in b)
    return sino(int(s))


def normalize_ko(text: str) -> str:
    """숫자 · 단위를 읽는 말로 바꾼다."""
    t = re.sub(r"(\d+)\s*(" + "|".join(NATIVE_COUNTERS) + ")", lambda m: read_count(int(m.group(1)), m.group(2)), text)
    t = re.sub(r"(\d[\d,]*(?:\.\d+)?)\s*%", lambda m: read_number(m.group(1)) + " 퍼센트", t)
    t = re.sub(r"\d[\d,]*(?:\.\d+)?", lambda m: read_number(m.group(0)), t)
    return re.sub(r"\s+", " ", t).strip()

CHO = list("ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ")                                   # 19
JUNG = list("ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ")                             # 21
JONG = [""] + list("ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ")               # 28 (받침 없음 포함)


def decompose(ch: str):
    """음절 -> (초성, 중성, 종성). 한글 음절이 아니면 None"""
    code = ord(ch) - 0xAC00
    if not 0 <= code < 11172:
        return None
    return CHO[code // 588], JUNG[(code % 588) // 28], JONG[code % 28]


def compose(cho: str, jung: str, jong: str = "") -> str:
    return chr(0xAC00 + (CHO.index(cho) * 21 + JUNG.index(jung)) * 28 + JONG.index(jong))

SPLIT = {"ㄳ": ("ㄱ", "ㅅ"), "ㄵ": ("ㄴ", "ㅈ"), "ㄺ": ("ㄹ", "ㄱ"), "ㄻ": ("ㄹ", "ㅁ"), "ㄼ": ("ㄹ", "ㅂ"), "ㄾ": ("ㄹ", "ㅌ"),
         "ㄿ": ("ㄹ", "ㅍ"), "ㅄ": ("ㅂ", "ㅅ")}                                            # 겹받침: 뒤 자음이 넘어감
NASAL = {"ㄱ": "ㅇ", "ㄲ": "ㅇ", "ㅋ": "ㅇ", "ㄷ": "ㄴ", "ㅅ": "ㄴ", "ㅆ": "ㄴ", "ㅈ": "ㄴ", "ㅊ": "ㄴ", "ㅌ": "ㄴ", "ㅂ": "ㅁ", "ㅍ": "ㅁ"}


def g2p_word(word: str) -> str:
    """어절 하나에 연음 · 구개음화 · 비음화 · 유음화를 적용 (g2pk2 규칙 수십 개 중 대표 4개)"""
    syl = [list(decompose(c)) if decompose(c) else c for c in word]
    for i in range(len(syl) - 1):
        a, b = syl[i], syl[i + 1]
        if not (isinstance(a, list) and isinstance(b, list)) or not a[2]:
            continue
        if b[0] == "ㅇ" and a[2] not in ("ㅇ", "ㅎ"):
            if b[1] == "ㅣ" and a[2] in ("ㄷ", "ㅌ"):          # 구개음화: 같이 -> 가치
                a[2], b[0] = "", {"ㄷ": "ㅈ", "ㅌ": "ㅊ"}[a[2]]
            else:                                               # 연음: 밥을 -> 바블
                keep, move = SPLIT.get(a[2], ("", a[2]))
                a[2], b[0] = keep, move
        elif b[0] in ("ㄴ", "ㅁ") and a[2] in NASAL:            # 비음화: 국물 -> 궁물, 합니다 -> 함니다
            a[2] = NASAL[a[2]]
        elif b[0] == "ㄹ" and a[2] == "ㄴ":                     # 유음화: 신라 -> 실라
            a[2] = "ㄹ"
    return "".join(compose(*s) if isinstance(s, list) else s for s in syl)


def g2p(text: str) -> str:
    return " ".join(g2p_word(w) for w in text.split(" "))

VOWELS = set(JUNG)


def to_jamo(text: str) -> list:
    """발음 열 -> 자모 열 (소리 없는 초성 ㅇ은 뺌, 띄어쓰기는 '_')"""
    out = []
    for c in text:
        d = decompose(c)
        if d:
            out += [j for k, j in enumerate(d) if j and not (k == 0 and j == "ㅇ")]
        elif c == " ":
            out.append("_")
    return out


def toy_durations(phones: list) -> np.ndarray:
    """장난감 길이: 모음 9 · 자음 4 · 쉼 6 프레임 (진짜는 Acoustic Model이 예측)"""
    return np.array([9 if p in VOWELS else (6 if p == "_" else 4) for p in phones])

HOP = 256                      # mel 한 프레임이 소리 256 샘플 (16kHz에서 16ms)
RATES = [8, 8, 2, 2]           # HiFi-GAN 업샘플 단계: 8 x 8 x 2 x 2 = 256
SR = 16000


def upsample(x: np.ndarray, r: int) -> np.ndarray:
    """프레임 열을 r배 촘촘하게 (ConvTranspose1d 업샘플 흉내: 선형 보간)"""
    return np.interp(np.arange(len(x) * r) / r, np.arange(len(x)), x)


def toy_vocoder(f0: np.ndarray, amp: np.ndarray) -> np.ndarray:
    """프레임별 (음높이, 세기) -> 파형. 학습한 신경망 대신 사인파 합성으로 '프레임 x 256 = 샘플' 흐름만 재현"""
    for r in RATES:
        f0, amp = upsample(f0, r), upsample(amp, r)
    phase = 2 * np.pi * np.cumsum(f0) / SR
    return (amp * np.sin(phase)).astype(np.float32)


text = "가격은 12,500원입니다"
norm = normalize_ko(text)                                    # 1) 정규화: 숫자를 읽는 말로
pron = g2p(norm)                                             # 2) G2P: 소리 나는 대로
phones = to_jamo(pron)                                       # 3) 발음 기호(자모) 열
durations = toy_durations(phones)                            # 4) Acoustic Model: 기호마다 길이 (진짜는 mel도 예측)
frame_phone = np.repeat(np.arange(len(phones)), durations)   # 5) Length Regulator: 길이만큼 복사
is_vowel = np.array([phones[i] in VOWELS for i in frame_phone])
f0 = np.where(is_vowel, 180.0, 120.0)
amp = np.where(is_vowel, 0.3, 0.08)
y = toy_vocoder(f0, amp)                                     # 6) Vocoder: 프레임 x 256 = 샘플
print(text, "->", norm, "->", pron)
print(f"기호 {len(phones)}개 -> 프레임 {len(frame_phone)}개 -> 샘플 {len(y):,} ({len(y) / SR:.2f}초)")
check(norm == "가격은 만이천오백원입니다" and pron.startswith("가겨근") and len(y) == len(frame_phone) * HOP
      and len(frame_phone) == int(durations.sum()))

flow.typescript:
// D16 · Part 0~7 · 오늘의 흐름 전체: 글자 → 정규화 → 발음 → 길이 → mel → 소리 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d16_flow.ts
//   정규화 · G2P · 자모 · duration · Length Regulator · 업샘플까지 한 줄로 이어 확인 (신경망 대신 규칙 · 사인파)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const DIGITS = "영일이삼사오육칠팔구";
const ONES = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉"];
const TENS = ["", "열", "스물", "서른", "마흔", "쉰", "예순", "일흔", "여든", "아흔"];
const NATIVE_COUNTERS = ["시간", "개", "명", "살", "마리", "권", "잔", "병", "장", "달", "시"]; // '시간'을 '시'보다 먼저

function sino(num: number): string {
  // 한자어 수: 12500 -> 만이천오백
  let n = num;
  if (n === 0) return "영";
  let out = "";
  for (const big of ["", "만", "억", "조"]) { // 네 자리씩 끊어 읽기
    let chunk = n % 10000;
    n = Math.floor(n / 10000);
    let s = "";
    ["", "십", "백", "천"].forEach((unit, i) => {
      const d = chunk % 10;
      chunk = Math.floor(chunk / 10);
      if (d) s = (d === 1 && i > 0 ? "" : DIGITS[d]) + unit + s;
    });
    if (s) out = (s === "일" && big === "만" ? "" : s) + big + out;
    if (n === 0) break;
  }
  return out;
}

function native(n: number): string {
  // 고유어 수: 3 -> 세, 20 -> 스무, 21 -> 스물한
  if (!(n > 0 && n < 100)) return sino(n);
  return n === 20 ? "스무" : TENS[Math.floor(n / 10)] + ONES[n % 10];
}

function readCount(n: number, unit: string): string {
  return (NATIVE_COUNTERS.includes(unit) ? native(n) : sino(n)) + " " + unit;
}

function readNumber(raw: string): string {
  const s = raw.replace(/,/g, "");
  if (s.includes(".")) {
    const [a, b] = s.split(".");
    return sino(parseInt(a, 10)) + "점" + [...b].map((c) => DIGITS[Number(c)]).join("");
  }
  return sino(parseInt(s, 10));
}

function normalizeKo(text: string): string {
  // 숫자 · 단위를 읽는 말로 바꾼다
  let t = text.replace(new RegExp("(\\d+)\\s*(" + NATIVE_COUNTERS.join("|") + ")", "g"), (_m, n, u) => readCount(parseInt(n, 10), u));
  t = t.replace(/(\d[\d,]*(?:\.\d+)?)\s*%/g, (_m, n) => readNumber(n) + " 퍼센트");
  t = t.replace(/\d[\d,]*(?:\.\d+)?/g, (m) => readNumber(m));
  return t.replace(/\s+/g, " ").trim();
}

const CHO = [..."ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"]; // 19
const JUNG = [..."ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"]; // 21
const JONG = ["", ..."ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ"]; // 28 (받침 없음 포함)

function decompose(ch: string): string[] | null {
  // 음절 -> [초성, 중성, 종성]. 한글 음절이 아니면 null
  const code = ch.charCodeAt(0) - 0xac00;
  if (!(code >= 0 && code < 11172)) return null;
  return [CHO[Math.floor(code / 588)], JUNG[Math.floor((code % 588) / 28)], JONG[code % 28]];
}

function compose(cho: string, jung: string, jong: string = ""): string {
  return String.fromCharCode(0xac00 + (CHO.indexOf(cho) * 21 + JUNG.indexOf(jung)) * 28 + JONG.indexOf(jong));
}

const SPLIT: Record<string, string[]> = { "ㄳ": ["ㄱ", "ㅅ"], "ㄵ": ["ㄴ", "ㅈ"], "ㄺ": ["ㄹ", "ㄱ"], "ㄻ": ["ㄹ", "ㅁ"], "ㄼ": ["ㄹ", "ㅂ"], "ㄾ": ["ㄹ", "ㅌ"], "ㄿ": ["ㄹ", "ㅍ"], "ㅄ": ["ㅂ", "ㅅ"] }; // 겹받침: 뒤 자음이 넘어감
const NASAL: Record<string, string> = { "ㄱ": "ㅇ", "ㄲ": "ㅇ", "ㅋ": "ㅇ", "ㄷ": "ㄴ", "ㅅ": "ㄴ", "ㅆ": "ㄴ", "ㅈ": "ㄴ", "ㅊ": "ㄴ", "ㅌ": "ㄴ", "ㅂ": "ㅁ", "ㅍ": "ㅁ" };

function g2pWord(word: string): string {
  // 어절 하나에 연음 · 구개음화 · 비음화 · 유음화를 적용 (g2pk2 규칙 수십 개 중 대표 4개)
  const syl: (string[] | string)[] = [...word].map((c) => decompose(c) ?? c);
  for (let i = 0; i < syl.length - 1; i++) {
    const a = syl[i];
    const b = syl[i + 1];
    if (typeof a === "string" || typeof b === "string" || !a[2]) continue;
    if (b[0] === "ㅇ" && a[2] !== "ㅇ" && a[2] !== "ㅎ") {
      if (b[1] === "ㅣ" && (a[2] === "ㄷ" || a[2] === "ㅌ")) { // 구개음화: 같이 -> 가치
        b[0] = a[2] === "ㄷ" ? "ㅈ" : "ㅊ";
        a[2] = "";
      } else { // 연음: 밥을 -> 바블
        const [keep, move] = SPLIT[a[2]] ?? ["", a[2]];
        a[2] = keep;
        b[0] = move;
      }
    } else if ((b[0] === "ㄴ" || b[0] === "ㅁ") && a[2] in NASAL) { // 비음화: 국물 -> 궁물, 합니다 -> 함니다
      a[2] = NASAL[a[2]];
    } else if (b[0] === "ㄹ" && a[2] === "ㄴ") { // 유음화: 신라 -> 실라
      a[2] = "ㄹ";
    }
  }
  return syl.map((s) => (typeof s === "string" ? s : compose(s[0], s[1], s[2]))).join("");
}

function g2p(text: string): string {
  return text.split(" ").map(g2pWord).join(" ");
}

const VOWELS = new Set(JUNG);

function toJamo(text: string): string[] {
  // 발음 열 -> 자모 열 (소리 없는 초성 ㅇ은 뺌, 띄어쓰기는 '_')
  const out: string[] = [];
  for (const c of text) {
    const d = decompose(c);
    if (d) d.forEach((j, k) => { if (j && !(k === 0 && j === "ㅇ")) out.push(j); });
    else if (c === " ") out.push("_");
  }
  return out;
}

function toyDurations(phones: string[]): number[] {
  // 장난감 길이: 모음 9 · 자음 4 · 쉼 6 프레임 (진짜는 Acoustic Model이 예측)
  return phones.map((p) => (VOWELS.has(p) ? 9 : p === "_" ? 6 : 4));
}

const HOP = 256; // mel 한 프레임이 소리 256 샘플 (16kHz에서 16ms)
const RATES = [8, 8, 2, 2]; // HiFi-GAN 업샘플 단계: 8 x 8 x 2 x 2 = 256
const SR = 16000;

function upsample(x: number[], r: number): number[] {
  // 프레임 열을 r배 촘촘하게 (ConvTranspose1d 업샘플 흉내: 선형 보간)
  const out: number[] = [];
  for (let i = 0; i < x.length * r; i++) {
    const p = i / r;
    const k = Math.min(Math.floor(p), x.length - 1);
    const k2 = Math.min(k + 1, x.length - 1);
    out.push(x[k] + (x[k2] - x[k]) * (p - k));
  }
  return out;
}

function toyVocoder(f0In: number[], ampIn: number[]): Float32Array {
  // 프레임별 (음높이, 세기) -> 파형. 학습한 신경망 대신 사인파 합성으로 '프레임 x 256 = 샘플' 흐름만 재현
  let f0 = f0In;
  let amp = ampIn;
  for (const r of RATES) {
    f0 = upsample(f0, r);
    amp = upsample(amp, r);
  }
  const y = new Float32Array(f0.length);
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    phase += (2 * Math.PI * f0[i]) / SR;
    y[i] = amp[i] * Math.sin(phase);
  }
  return y;
}

const text = "가격은 12,500원입니다";
const norm = normalizeKo(text); // 1) 정규화: 숫자를 읽는 말로
const pron = g2p(norm); // 2) G2P: 소리 나는 대로
const phones = toJamo(pron); // 3) 발음 기호(자모) 열
const durations = toyDurations(phones); // 4) Acoustic Model: 기호마다 길이 (진짜는 mel도 예측)
const framePhone: number[] = durations.flatMap((d, i) => new Array(d).fill(i)); // 5) Length Regulator: 길이만큼 복사
const isVowel = framePhone.map((i) => VOWELS.has(phones[i]));
const y = toyVocoder(isVowel.map((v) => (v ? 180 : 120)), isVowel.map((v) => (v ? 0.3 : 0.08))); // 6) Vocoder: 프레임 x 256 = 샘플
console.log(text, "->", norm, "->", pron);
console.log(`기호 ${phones.length}개 -> 프레임 ${framePhone.length}개 -> 샘플 ${y.length} (${(y.length / SR).toFixed(2)}초)`);
check(norm === "가격은 만이천오백원입니다" && pron.startsWith("가겨근") && y.length === framePhone.length * HOP
  && framePhone.length === durations.reduce((a, b) => a + b, 0));

norm.python:
# D16 · Part 2 · 텍스트 정규화: 읽는 대로 글자를 고치기 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d16_norm.py   (인터넷 · GPU · 마이크 불필요)
#   숫자 → 한자어 · 고유어 읽기, 단위 · 퍼센트 읽기를 규칙으로 직접 구현
import re

def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
