// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d16_g2p.ts
//   연음 · 구개음화 · 비음화 · 유음화 규칙으로 글자를 발음으로 바꾸기 (g2pk2 대신 직접 구현)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const CHO = [..."ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"]; // 19
const JUNG = [..."ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"]; // 21
const JONG = ["", ..."ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ"]; // 28 (받침 없음 포함)

function decompose(ch: string): string[] | null {
  // 음절 -> [초성, 중성, 종성]. 한글 음절이 아니면 null
  const code = ch.charCodeAt(0) - 0xac00;
  if (!(code >= 0 && code < 11172)) return null;
  return [CHO[Math.floor(code / 588)], JUNG[Math.floor((code % 588) / 28)], JONG[code % 28]];
}

function compose(cho: string, jung: string, jong: string = ""): string {
  return String.fromCharCode(0xac00 + (CHO.indexOf(cho) * 21 + JUNG.indexOf(jung)) * 28 + JONG.indexOf(jong));
}

const SPLIT: Record<string, string[]> = { "ㄳ": ["ㄱ", "ㅅ"], "ㄵ": ["ㄴ", "ㅈ"], "ㄺ": ["ㄹ", "ㄱ"], "ㄻ": ["ㄹ", "ㅁ"], "ㄼ": ["ㄹ", "ㅂ"], "ㄾ": ["ㄹ", "ㅌ"], "ㄿ": ["ㄹ", "ㅍ"], "ㅄ": ["ㅂ", "ㅅ"] }; // 겹받침: 뒤 자음이 넘어감
const NASAL: Record<string, string> = { "ㄱ": "ㅇ", "ㄲ": "ㅇ", "ㅋ": "ㅇ", "ㄷ": "ㄴ", "ㅅ": "ㄴ", "ㅆ": "ㄴ", "ㅈ": "ㄴ", "ㅊ": "ㄴ", "ㅌ": "ㄴ", "ㅂ": "ㅁ", "ㅍ": "ㅁ" };

function g2pWord(word: string): string {
  // 어절 하나에 연음 · 구개음화 · 비음화 · 유음화를 적용 (g2pk2 규칙 수십 개 중 대표 4개)
  const syl: (string[] | string)[] = [...word].map((c) => decompose(c) ?? c);
  for (let i = 0; i < syl.length - 1; i++) {
    const a = syl[i];
    const b = syl[i + 1];
    if (typeof a === "string" || typeof b === "string" || !a[2]) continue;
    if (b[0] === "ㅇ" && a[2] !== "ㅇ" && a[2] !== "ㅎ") {
      if (b[1] === "ㅣ" && (a[2] === "ㄷ" || a[2] === "ㅌ")) { // 구개음화: 같이 -> 가치
        b[0] = a[2] === "ㄷ" ? "ㅈ" : "ㅊ";
        a[2] = "";
      } else { // 연음: 밥을 -> 바블
        const [keep, move] = SPLIT[a[2]] ?? ["", a[2]];
        a[2] = keep;
        b[0] = move;
      }
    } else if ((b[0] === "ㄴ" || b[0] === "ㅁ") && a[2] in NASAL) { // 비음화: 국물 -> 궁물, 합니다 -> 함니다
      a[2] = NASAL[a[2]];
    } else if (b[0] === "ㄹ" && a[2] === "ㄴ") { // 유음화: 신라 -> 실라
      a[2] = "ㄹ";
    }
  }
  return syl.map((s) => (typeof s === "string" ? s : compose(s[0], s[1], s[2]))).join("");
}

function g2p(text: string): string {
  return text.split(" ").map(g2pWord).join(" ");
}

const WORDS = ["밥을", "음악", "국어", "닭이", "값이", "앉아", "같이", "국물", "신라", "합니다"];
for (const w of WORDS) console.log(`${w} -> ${g2pWord(w)}`);
check(g2pWord("밥을") === "바블" && g2pWord("닭이") === "달기" && g2pWord("값이") === "갑시"
  && g2pWord("같이") === "가치" && g2pWord("국물") === "궁물" && g2pWord("신라") === "실라"
  && g2pWord("합니다") === "함니다" && g2p("밥을 먹어요") === "바블 머거요");

mel.typescript:
// D16 · Part 4 · Acoustic Model의 목표: 소리 그림(mel) 만들기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d16_mel.ts
//   STFT → mel 필터 80개 → (80, 프레임), 프레임 수 = 1 + 샘플 / hop (440 Hz 사인파로 확인)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const SR = 16000;
const N_FFT = 1024;
const HOP = 256;
const N_MELS = 80;
const FMIN = 80;
const FMAX = 7600;

const hzToMel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const melToHz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melPoints(): number[] {
  // mel 눈금에서 같은 간격으로 고른 경계 주파수 (N_MELS + 2개)
  const a = hzToMel(FMIN);
  const b = hzToMel(FMAX);
  return Array.from({ length: N_MELS + 2 }, (_, i) => melToHz(a + ((b - a) * i) / (N_MELS + 1)));
}

function fft(re: number[], im: number[]): void {
  // 제자리 radix-2 FFT (길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) { [re[i], re[j]] = [re[j], re[i]]; [im[i], im[j]] = [im[j], im[i]]; }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr; im[b] = im[a] - xi;
        re[a] += xr; im[a] += xi;
      }
    }
  }
}

function melSpectrogram(y: Float32Array): number[][] {
  const half = N_FFT / 2;
  const nFrames = 1 + Math.floor(y.length / HOP);
  const at = (i: number): number => { // 양끝을 반사해서 채움 (center=True)
    let k = i - half;
    if (k < 0) k = -k;
    if (k >= y.length) k = 2 * (y.length - 1) - k;
    return y[k];
  };
  const pts = melPoints();
  const fb: number[][] = [];
  for (let k = 0; k < N_MELS; k++) { // 삼각형 필터 80개
    const [lo, mid, hi] = [pts[k], pts[k + 1], pts[k + 2]];
    fb.push(Array.from({ length: half + 1 }, (_, b) => {
      const f = (b * SR) / N_FFT;
      return Math.max(0, Math.min((f - lo) / (mid - lo), (hi - f) / (hi - mid)));
    }));
  }
  const M: number[][] = Array.from({ length: N_MELS }, () => new Array(nFrames).fill(0));
  for (let t = 0; t < nFrames; t++) {
    const re = Array.from({ length: N_FFT }, (_, i) => at(t * HOP + i) * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / N_FFT))); // Hann 창
    const im = new Array(N_FFT).fill(0);
    fft(re, im);
    const power = Array.from({ length: half + 1 }, (_, b) => re[b] ** 2 + im[b] ** 2);
    for (let k = 0; k < N_MELS; k++) M[k][t] = fb[k].reduce((s, w, b) => s + w * power[b], 0);
  }
  return M;
}

const y = Float32Array.from({ length: SR }, (_, i) => 0.3 * Math.sin((2 * Math.PI * 440 * i) / SR)); // 합성 신호: 440 Hz 사인파 1초
const M = melSpectrogram(y);
const nFrames = 1 + Math.floor(y.length / HOP);
const means = M.map((row) => row.reduce((a, b) => a + b, 0) / row.length);
const peakBin = means.indexOf(Math.max(...means));
const peakHz = melPoints()[peakBin + 1];
console.log(`소리 ${y.length} 샘플 · mel (${M.length}, ${M[0].length}) · 계산한 프레임 수 ${nFrames} · 1초 = ${SR / HOP} 프레임`);
console.log(`가장 센 mel 칸 ${peakBin}번 (중심 ${peakHz.toFixed(0)} Hz)`);
check(M.length === N_MELS && M[0].length === nFrames && Math.abs(peakHz - 440) < 60, "프레임 수 = 1 + 샘플 // HOP");

duration.typescript:
// D16 · Part 4-1 · Duration과 Length Regulator (FastSpeech 방식) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d16_duration.ts
//   발음 기호마다 길이(프레임)를 곱해 늘리고, speaking_rate로 전체 길이 조절
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const CHO = [..."ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"]; // 19
const JUNG = [..."ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"]; // 21
const JONG = ["", ..."ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ"]; // 28 (받침 없음 포함)

function decompose(ch: string): string[] | null {
  // 음절 -> [초성, 중성, 종성]. 한글 음절이 아니면 null
  const code = ch.charCodeAt(0) - 0xac00;
  if (!(code >= 0 && code < 11172)) return null;
  return [CHO[Math.floor(code / 588)], JUNG[Math.floor((code % 588) / 28)], JONG[code % 28]];
}

function compose(cho: string, jung: string, jong: string = ""): string {
  return String.fromCharCode(0xac00 + (CHO.indexOf(cho) * 21 + JUNG.indexOf(jung)) * 28 + JONG.indexOf(jong));
}

const SPLIT: Record<string, string[]> = { "ㄳ": ["ㄱ", "ㅅ"], "ㄵ": ["ㄴ", "ㅈ"], "ㄺ": ["ㄹ", "ㄱ"], "ㄻ": ["ㄹ", "ㅁ"], "ㄼ": ["ㄹ", "ㅂ"], "ㄾ": ["ㄹ", "ㅌ"], "ㄿ": ["ㄹ", "ㅍ"], "ㅄ": ["ㅂ", "ㅅ"] }; // 겹받침: 뒤 자음이 넘어감
const NASAL: Record<string, string> = { "ㄱ": "ㅇ", "ㄲ": "ㅇ", "ㅋ": "ㅇ", "ㄷ": "ㄴ", "ㅅ": "ㄴ", "ㅆ": "ㄴ", "ㅈ": "ㄴ", "ㅊ": "ㄴ", "ㅌ": "ㄴ", "ㅂ": "ㅁ", "ㅍ": "ㅁ" };

function g2pWord(word: string): string {
  // 어절 하나에 연음 · 구개음화 · 비음화 · 유음화를 적용 (g2pk2 규칙 수십 개 중 대표 4개)
  const syl: (string[] | string)[] = [...word].map((c) => decompose(c) ?? c);
  for (let i = 0; i < syl.length - 1; i++) {
    const a = syl[i];
    const b = syl[i + 1];
    if (typeof a === "string" || typeof b === "string" || !a[2]) continue;
    if (b[0] === "ㅇ" && a[2] !== "ㅇ" && a[2] !== "ㅎ") {
      if (b[1] === "ㅣ" && (a[2] === "ㄷ" || a[2] === "ㅌ")) { // 구개음화: 같이 -> 가치
        b[0] = a[2] === "ㄷ" ? "ㅈ" : "ㅊ";
        a[2] = "";
      } else { // 연음: 밥을 -> 바블
        const [keep, move] = SPLIT[a[2]] ?? ["", a[2]];
        a[2] = keep;
        b[0] = move;
      }
    } else if ((b[0] === "ㄴ" || b[0] === "ㅁ") && a[2] in NASAL) { // 비음화: 국물 -> 궁물, 합니다 -> 함니다
      a[2] = NASAL[a[2]];
    } else if (b[0] === "ㄹ" && a[2] === "ㄴ") { // 유음화: 신라 -> 실라
      a[2] = "ㄹ";
    }
  }
  return syl.map((s) => (typeof s === "string" ? s : compose(s[0], s[1], s[2]))).join("");
}

function g2p(text: string): string {
  return text.split(" ").map(g2pWord).join(" ");
}

const VOWELS = new Set(JUNG);

function toJamo(text: string): string[] {
  // 발음 열 -> 자모 열 (소리 없는 초성 ㅇ은 뺌, 띄어쓰기는 '_')
  const out: string[] = [];
  for (const c of text) {
    const d = decompose(c);
    if (d) d.forEach((j, k) => { if (j && !(k === 0 && j === "ㅇ")) out.push(j); });
    else if (c === " ") out.push("_");
  }
  return out;
}

function toyDurations(phones: string[]): number[] {
  // 장난감 길이: 모음 9 · 자음 4 · 쉼 6 프레임 (진짜는 Acoustic Model이 예측)
  return phones.map((p) => (VOWELS.has(p) ? 9 : p === "_" ? 6 : 4));
}

const HOP = 256;
const SR = 16000;

const phones = toJamo(g2p("밥을 먹었다"));
const durations = toyDurations(phones);
// Length Regulator: 기호 번호를 길이만큼 복사 (one-hot 행 대신 번호로 표현)
const frameOf: number[] = durations.flatMap((d, i) => new Array(d).fill(i));
console.log("발음 열:", phones.join(" "));
console.log(`발음 기호 ${phones.length}개 -> 프레임 ${frameOf.length}개 = ${((frameOf.length * HOP) / SR).toFixed(2)}초`);

const totals: Record<string, number> = {};
for (const rate of [0.8, 1.0, 1.5]) { // 말 빠르기: duration / rate
  const total = durations.reduce((a, d) => a + Math.ceil(d / rate), 0);
  totals[String(rate)] = total;
  console.log(`  speaking_rate ${rate}: ${total} 프레임 = ${((total * HOP) / SR).toFixed(2)}초`);
}
const sum = durations.reduce((a, b) => a + b, 0);
check(frameOf.length === sum && frameOf[0] === 0 && frameOf[frameOf.length - 1] === phones.length - 1
  && totals["0.8"] > totals["1"] && totals["1"] > totals["1.5"]);

vocoder.typescript:
// D16 · Part 5 · Vocoder: 소리 그림을 진짜 소리로 (업샘플 8 x 8 x 2 x 2 = 256) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d16_vocoder.ts
//   프레임 열을 단계마다 늘려 파형을 만든다. 학습한 HiFi-GAN 대신 사인파 합성
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const HOP = 256; // mel 한 프레임이 소리 256 샘플 (16kHz에서 16ms)
const RATES = [8, 8, 2, 2]; // HiFi-GAN 업샘플 단계: 8 x 8 x 2 x 2 = 256
const SR = 16000;

function upsample(x: number[], r: number): number[] {
  // 프레임 열을 r배 촘촘하게 (ConvTranspose1d 업샘플 흉내: 선형 보간)
  const out: number[] = [];
  for (let i = 0; i < x.length * r; i++) {
    const p = i / r;
    const k = Math.min(Math.floor(p), x.length - 1);
    const k2 = Math.min(k + 1, x.length - 1);
    out.push(x[k] + (x[k2] - x[k]) * (p - k));
  }
  return out;
}

function toyVocoder(f0In: number[], ampIn: number[]): Float32Array {
  // 프레임별 (음높이, 세기) -> 파형. 학습한 신경망 대신 사인파 합성으로 '프레임 x 256 = 샘플' 흐름만 재현
  let f0 = f0In;
  let amp = ampIn;
  for (const r of RATES) {
    f0 = upsample(f0, r);
    amp = upsample(amp, r);
  }
  const y = new Float32Array(f0.length);
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    phase += (2 * Math.PI * f0[i]) / SR;
    y[i] = amp[i] * Math.sin(phase);
  }
  return y;
}

const T = 60; // mel 60프레임 (약 0.96초)
const f0 = Array.from({ length: T }, (_, i) => 150 + (150 * i) / (T - 1)); // 프레임마다 음높이 150 -> 300 Hz (장난감 mel이 담은 정보)
const amp = new Array(T).fill(0.4);
const y = toyVocoder(f0, amp);
const hop = RATES.reduce((a, b) => a * b, 1);
console.log(`프레임 ${T}개 -> 파형 ${y.length} 샘플 · 업샘플 [${RATES}] -> x${hop} · ${(y.length / SR).toFixed(2)}초`);

let crossings = 0; // 올라가며 0을 지난 횟수 = 주기 수
for (let i = 1; i < y.length; i++) if (y[i - 1] < 0 && y[i] >= 0) crossings++;
const avgHz = crossings / (y.length / SR);
console.log(`0 교차로 잰 평균 음높이 ${avgHz.toFixed(0)} Hz (150 ~ 300의 중간 225 근처)`);
check(hop === 256 && y.length === T * hop && Math.abs(avgHz - 225) < 15, "업샘플 배수의 곱 = HOP");

vits.typescript:
// D16 · Part 6 · End-to-end: VITS가 입력 기호마다 duration을 꺼내는 과정 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d16_vits.ts
//   로마자 기호 + blank → duration 예측 → 프레임 x hop = 파형 길이, speaking_rate · noise_scale 손잡이
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const CHO = [..."ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"]; // 19
const JUNG = [..."ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"]; // 21
const JONG = ["", ..."ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ"]; // 28 (받침 없음 포함)

function decompose(ch: string): string[] | null {
  // 음절 -> [초성, 중성, 종성]. 한글 음절이 아니면 null
  const code = ch.charCodeAt(0) - 0xac00;
  if (!(code >= 0 && code < 11172)) return null;
  return [CHO[Math.floor(code / 588)], JUNG[Math.floor((code % 588) / 28)], JONG[code % 28]];
}

function compose(cho: string, jung: string, jong: string = ""): string {
  return String.fromCharCode(0xac00 + (CHO.indexOf(cho) * 21 + JUNG.indexOf(jung)) * 28 + JONG.indexOf(jong));
}

const SPLIT: Record<string, string[]> = { "ㄳ": ["ㄱ", "ㅅ"], "ㄵ": ["ㄴ", "ㅈ"], "ㄺ": ["ㄹ", "ㄱ"], "ㄻ": ["ㄹ", "ㅁ"], "ㄼ": ["ㄹ", "ㅂ"], "ㄾ": ["ㄹ", "ㅌ"], "ㄿ": ["ㄹ", "ㅍ"], "ㅄ": ["ㅂ", "ㅅ"] }; // 겹받침: 뒤 자음이 넘어감
const NASAL: Record<string, string> = { "ㄱ": "ㅇ", "ㄲ": "ㅇ", "ㅋ": "ㅇ", "ㄷ": "ㄴ", "ㅅ": "ㄴ", "ㅆ": "ㄴ", "ㅈ": "ㄴ", "ㅊ": "ㄴ", "ㅌ": "ㄴ", "ㅂ": "ㅁ", "ㅍ": "ㅁ" };

function g2pWord(word: string): string {
  // 어절 하나에 연음 · 구개음화 · 비음화 · 유음화를 적용 (g2pk2 규칙 수십 개 중 대표 4개)
  const syl: (string[] | string)[] = [...word].map((c) => decompose(c) ?? c);
  for (let i = 0; i < syl.length - 1; i++) {
    const a = syl[i];
    const b = syl[i + 1];
    if (typeof a === "string" || typeof b === "string" || !a[2]) continue;
    if (b[0] === "ㅇ" && a[2] !== "ㅇ" && a[2] !== "ㅎ") {
      if (b[1] === "ㅣ" && (a[2] === "ㄷ" || a[2] === "ㅌ")) { // 구개음화: 같이 -> 가치
        b[0] = a[2] === "ㄷ" ? "ㅈ" : "ㅊ";
        a[2] = "";
      } else { // 연음: 밥을 -> 바블
        const [keep, move] = SPLIT[a[2]] ?? ["", a[2]];
        a[2] = keep;
        b[0] = move;
      }
    } else if ((b[0] === "ㄴ" || b[0] === "ㅁ") && a[2] in NASAL) { // 비음화: 국물 -> 궁물, 합니다 -> 함니다
      a[2] = NASAL[a[2]];
    } else if (b[0] === "ㄹ" && a[2] === "ㄴ") { // 유음화: 신라 -> 실라
      a[2] = "ㄹ";
    }
  }
  return syl.map((s) => (typeof s === "string" ? s : compose(s[0], s[1], s[2]))).join("");
}

function g2p(text: string): string {
  return text.split(" ").map(g2pWord).join(" ");
}

const CHO_R = ["g", "kk", "n", "d", "tt", "r", "m", "b", "pp", "s", "ss", "", "j", "jj", "ch", "k", "t", "p", "h"];
const JUNG_R = ["a", "ae", "ya", "yae", "eo", "e", "yeo", "ye", "o", "wa", "wae", "oe", "yo", "u", "wo", "we", "wi", "yu", "eu", "ui", "i"];
const JONG_R = ["", "g", "kk", "gs", "n", "nj", "nh", "d", "l", "lg", "lm", "lb", "ls", "lt", "lp", "lh", "m", "b", "bs", "s", "ss", "ng", "j", "ch", "k", "t", "p", "h"];

function romanize(text: string): string {
  // 한글 -> 로마자 (uroman 흉내: 자모 표 조회)
  return [...text].map((c) => {
    const d = decompose(c);
    return d ? CHO_R[CHO.indexOf(d[0])] + JUNG_R[JUNG.indexOf(d[1])] + JONG_R[JONG.indexOf(d[2])] : c.toLowerCase();
  }).join("");
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const TTS_SR = 16000;
const HOP_V = 256;
const VOCAB = new Set("abcdefghijklmnopqrstuvwxyz '"); // 모델이 아는 기호 (MMS-TTS도 로마자 소문자 위주)
const VOWEL_LETTERS = new Set("aeiouy");

function encode(roman: string): (string | number)[] {
  // 모르는 기호는 지우고, 기호 사이사이에 blank(0)를 끼운다: [0, c1, 0, c2, ..., 0]
  const ids: (string | number)[] = [0];
  for (const c of roman) if (VOCAB.has(c)) ids.push(c, 0);
  return ids;
}

function predictDur(ids: (string | number)[], speakingRate: number, noiseScale: number, seed: number): number[] {
  // duration predictor 흉내: 모음은 길게, 자음은 짧게, blank는 아주 짧게 + 무작위성(noise_scale)
  const r = rng(seed);
  return ids.map((c) => {
    const base = c === 0 ? Math.log(0.7) : VOWEL_LETTERS.has(c as string) ? Math.log(3.0) : Math.log(1.6);
    return Math.ceil(Math.exp(base + noiseScale * 0.3 * gauss(r)) / speakingRate); // 기호마다 프레임 수
  });
}

function synth(roman: string, speakingRate = 1.0, noiseScale = 0.667, seed = 0) {
  // 기호별 duration(프레임) -> 프레임마다 hop(256) 샘플의 파형 (flow + HiFi-GAN 디코더 대신 사인파 합성)
  const ids = encode(roman);
  const dur = predictDur(ids, speakingRate, noiseScale, seed);
  const n = dur.reduce((a, b) => a + b, 0) * HOP_V;
  const y = new Float32Array(n);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    phase += (2 * Math.PI * (140 + (60 * i) / n)) / TTS_SR;
    y[i] = 0.3 * Math.sin(phase);
  }
  return { y, ids, dur };
}

const roman = romanize(g2p("같이 밥을 먹으러 갈까요"));
const { y, ids, dur } = synth(roman);
const total = dur.reduce((a, b) => a + b, 0);
console.log("로마자:", roman);
console.log(`기호 ${ids.length}개(blank 포함) · 프레임 합 ${total} x hop ${HOP_V} = ${total * HOP_V} 샘플 · 실제 파형 ${y.length} 샘플`);
const slow = synth(roman, 0.8).y;
const fast = synth(roman, 1.3).y;
console.log(`speaking_rate 0.8 -> ${(slow.length / TTS_SR).toFixed(2)}초 · 1.0 -> ${(y.length / TTS_SR).toFixed(2)}초 · 1.3 -> ${(fast.length / TTS_SR).toFixed(2)}초`);
const same = synth(roman, 1, 0, 1).dur.join() === synth(roman, 1, 0, 2).dur.join();
console.log("noise_scale 0이면 씨앗이 달라도 같은 소리:", same);
check(total * HOP_V === y.length && slow.length > y.length && y.length > fast.length && same && ids[0] === 0 && ids[ids.length - 1] === 0);

backcheck.python:
# D16 · Part 7 · 정규화 · G2P는 얼마나 도움이 될까: 역검증 CER — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d16_backcheck.py   (인터넷 · GPU · 마이크 불필요)
#   원문 / G2P만 / 정규화+G2P 세 방식으로 모델 입력을 만들고, 지워지는 기호만큼 틀리는 장난감 ASR로 CER 비교
import re

def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")

DIGITS = "영일이삼사오육칠팔구"
ONES = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉"]
TENS = ["", "열", "스물", "서른", "마흔", "쉰", "예순", "일흔", "여든", "아흔"]
NATIVE_COUNTERS = ["시간", "개", "명", "살", "마리", "권", "잔", "병", "장", "달", "시"]   # '시간'을 '시'보다 먼저


def sino(n: int) -> str:
    """한자어 수: 12500 -> 만이천오백"""
    if n == 0:
        return "영"
    out = ""
    for big in ["", "만", "억", "조"]:                  # 네 자리씩 끊어 읽기
        chunk, n = n % 10000, n // 10000
        s = ""
        for i, unit in enumerate(["", "십", "백", "천"]):
            d, chunk = chunk % 10, chunk // 10
            if d:
                s = ("" if d == 1 and i > 0 else DIGITS[d]) + unit + s
        if s:
            out = ("" if s == "일" and big == "만" else s) + big + out
        if n == 0:
            break
    return out


def native(n: int) -> str:
    """고유어 수: 3 -> 세, 20 -> 스무, 21 -> 스물한"""
    if not 0 < n < 100:
        return sino(n)
    return "스무" if n == 20 else TENS[n // 10] + ONES[n % 10]


def read_count(n: int, unit: str) -> str:
    return (native(n) if unit in NATIVE_COUNTERS else sino(n)) + " " + unit


def read_number(s: str) -> str:
    s = s.replace(",", "")
    if "." in s:
        a, b = s.split(".", 1)
        return sino(int(a)) + "점" + "".join(DIGITS[int(c)] for c in b)
    return sino(int(s))


def normalize_ko(text: str) -> str:
    """숫자 · 단위를 읽는 말로 바꾼다."""
    t = re.sub(r"(\d+)\s*(" + "|".join(NATIVE_COUNTERS) + ")", lambda m: read_count(int(m.group(1)), m.group(2)), text)
    t = re.sub(r"(\d[\d,]*(?:\.\d+)?)\s*%", lambda m: read_number(m.group(1)) + " 퍼센트", t)
    t = re.sub(r"\d[\d,]*(?:\.\d+)?", lambda m: read_number(m.group(0)), t)
    return re.sub(r"\s+", " ", t).strip()

CHO = list("ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ")                                   # 19
JUNG = list("ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ")                             # 21
JONG = [""] + list("ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ")               # 28 (받침 없음 포함)


def decompose(ch: str):
    """음절 -> (초성, 중성, 종성). 한글 음절이 아니면 None"""
    code = ord(ch) - 0xAC00
    if not 0 <= code < 11172:
        return None
    return CHO[code // 588], JUNG[(code % 588) // 28], JONG[code % 28]


def compose(cho: str, jung: str, jong: str = "") -> str:
    return chr(0xAC00 + (CHO.index(cho) * 21 + JUNG.index(jung)) * 28 + JONG.index(jong))

SPLIT = {"ㄳ": ("ㄱ", "ㅅ"), "ㄵ": ("ㄴ", "ㅈ"), "ㄺ": ("ㄹ", "ㄱ"), "ㄻ": ("ㄹ", "ㅁ"), "ㄼ": ("ㄹ", "ㅂ"), "ㄾ": ("ㄹ", "ㅌ"),
         "ㄿ": ("ㄹ", "ㅍ"), "ㅄ": ("ㅂ", "ㅅ")}                                            # 겹받침: 뒤 자음이 넘어감
NASAL = {"ㄱ": "ㅇ", "ㄲ": "ㅇ", "ㅋ": "ㅇ", "ㄷ": "ㄴ", "ㅅ": "ㄴ", "ㅆ": "ㄴ", "ㅈ": "ㄴ", "ㅊ": "ㄴ", "ㅌ": "ㄴ", "ㅂ": "ㅁ", "ㅍ": "ㅁ"}


def g2p_word(word: str) -> str:
    """어절 하나에 연음 · 구개음화 · 비음화 · 유음화를 적용 (g2pk2 규칙 수십 개 중 대표 4개)"""
    syl = [list(decompose(c)) if decompose(c) else c for c in word]
    for i in range(len(syl) - 1):
        a, b = syl[i], syl[i + 1]
        if not (isinstance(a, list) and isinstance(b, list)) or not a[2]:
            continue
        if b[0] == "ㅇ" and a[2] not in ("ㅇ", "ㅎ"):
            if b[1] == "ㅣ" and a[2] in ("ㄷ", "ㅌ"):          # 구개음화: 같이 -> 가치
                a[2], b[0] = "", {"ㄷ": "ㅈ", "ㅌ": "ㅊ"}[a[2]]
            else:                                               # 연음: 밥을 -> 바블
                keep, move = SPLIT.get(a[2], ("", a[2]))
                a[2], b[0] = keep, move
        elif b[0] in ("ㄴ", "ㅁ") and a[2] in NASAL:            # 비음화: 국물 -> 궁물, 합니다 -> 함니다
            a[2] = NASAL[a[2]]
        elif b[0] == "ㄹ" and a[2] == "ㄴ":                     # 유음화: 신라 -> 실라
            a[2] = "ㄹ"
    return "".join(compose(*s) if isinstance(s, list) else s for s in syl)


def g2p(text: str) -> str:
    return " ".join(g2p_word(w) for w in text.split(" "))

CHO_R = ["g", "kk", "n", "d", "tt", "r", "m", "b", "pp", "s", "ss", "", "j", "jj", "ch", "k", "t", "p", "h"]
JUNG_R = ["a", "ae", "ya", "yae", "eo", "e", "yeo", "ye", "o", "wa", "wae", "oe", "yo", "u", "wo", "we", "wi", "yu", "eu", "ui", "i"]
JONG_R = ["", "g", "kk", "gs", "n", "nj", "nh", "d", "l", "lg", "lm", "lb", "ls", "lt", "lp", "lh", "m", "b", "bs", "s", "ss", "ng", "j", "ch", "k", "t", "p", "h"]


def romanize(text: str) -> str:
    """한글 -> 로마자 (uroman 흉내: 자모 표 조회)"""
    out = []
    for c in text:
        d = decompose(c)
        out.append(CHO_R[CHO.index(d[0])] + JUNG_R[JUNG.index(d[1])] + JONG_R[JONG.index(d[2])] if d else c.lower())
    return "".join(out)

def edit_distance(a, b) -> int:
    """레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)"""
    prev = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        cur = [i]
        for j, y in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (x != y)))
        prev = cur
    return prev[-1]


def cer(ref: str, hyp: str) -> float:
    """글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100"""
    return 100 * edit_distance(ref, hyp) / max(len(ref), 1)

VOCAB = set("abcdefghijklmnopqrstuvwxyz '")                 # 모델이 아는 기호: 숫자 · % · 한글은 토크나이저가 지움
MODES = {"A 원문": lambda s: s, "B G2P": g2p, "C 정규화+G2P": lambda s: g2p(normalize_ko(s))}
SENTS = ["회의는 오후 3시 15분에 시작합니다", "할인율은 25%입니다", "가격은 12,500원입니다",
         "같이 밥을 먹으러 갈까요", "국물이 정말 맛있네요", "사과 3개와 우유 2병을 샀어요"]


def model_hears(text: str, mode: str) -> str:
    """모델 입력 만들기: 로마자로 바꾼 뒤 모르는 기호는 지워진다 (그 소리는 나지 않음)"""
    return "".join(c for c in romanize(MODES[mode](text)) if c in VOCAB)


def reference(text: str) -> str:
    """정답 소리: 정규화 + G2P 한 발음 (사람이 읽을 소리)"""
    return romanize(g2p(normalize_ko(text)))


mean = {}
for mode in MODES:
    scores = [cer(reference(s), model_hears(s, mode)) for s in SENTS]
    mean[mode] = sum(scores) / len(scores)
    print(f"{mode:12s} 평균 CER {mean[mode]:5.1f}%  " + " ".join(f"{x:4.0f}" for x in scores))
check(mean["C 정규화+G2P"] == 0 and mean["C 정규화+G2P"] < mean["B G2P"] <= mean["A 원문"], "C < B <= A 이어야 해요")

